.item-desc { font-size: 13px; color: var(--text-secondary); }

.overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0, 0, 0, 0.75); backdrop-filter: blur(10px); z-index: 200; display: flex; justify-content: flex-end; opacity: 0; pointer-events: none; transition: opacity 0.25s ease; }
.overlay.active { opacity: 1; pointer-events: auto; }

.drawer-content { width: 100%; max-width: 540px; height: 100%; background: var(--bg-base); border-left: 0.5px solid var(--separator); overflow-y: auto; transform: translateX(100%); transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1); display: flex; flex-direction: column; }
.overlay.active .drawer-content { transform: translateX(0); }

.nav-bar { position: sticky; top: 0; display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; background: rgba(28, 28, 30, 0.95); backdrop-filter: blur(20px); border-bottom: 0.5px solid var(--separator); z-index: 10; }
.back-btn { color: var(--accent-blue); font-size: 15px; background: none; border: none; cursor: pointer; padding: 0; font-weight: 600; }

.modal-body { padding: 24px; flex: 1; }
.p-section-title { font-size: 11px; text-transform: uppercase; color: var(--text-secondary); font-weight: 700; letter-spacing: 0.5px; margin: 24px 0 10px 4px; }
.info-box { background: var(--bg-grouped); border-radius: 12px; padding: 16px; font-size: 14px; line-height: 1.5; border: 1px solid rgba(255,255,255,0.05); }

.roadmap-list { display: flex; flex-direction: column; gap: 10px; }
.roadmap-step { background: var(--bg-grouped); border-radius: 12px; padding: 14px; border-left: 3px solid var(--accent-blue); }
.step-title { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.step-desc { font-size: 13px; color: var(--text-secondary); }
.roadmap-status { font-size: 10px; font-weight: 700; padding: 3px 8px; border-radius: 6px; text-transform: uppercase; white-space: nowrap; }
.roadmap-status.planned { background: rgba(255,255,255,0.08); color: var(--text-secondary); }
.roadmap-status.in_progress { background: rgba(10,132,255,0.15); color: var(--accent-blue); }
.roadmap-status.done { background: rgba(48,209,88,0.15); color: var(--accent-green); }

