.cc-collapse:hover { background: rgba(255,255,255,0.12); color: var(--text-primary); }
.cc-head-main { flex: 1; min-width: 0; }
.cc-head-title { font-size: 15px; font-weight: 600; line-height: 1.35; overflow-wrap: anywhere; }
.cc-head-meta { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 7px; }
.cc-muted { color: var(--text-secondary); font-weight: 400; }

.cc-pill { display: inline-flex; align-items: center; font-size: 11px; font-weight: 600; padding: 3px 9px; border-radius: 7px; background: rgba(255,255,255,0.07); color: var(--text-secondary); }
.cc-pill-work { background: rgba(255,159,10,0.15); color: var(--accent-orange); }
.cc-pill-ready { background: rgba(10,132,255,0.15); color: var(--accent-blue); }
.cc-pill-done { background: rgba(48,209,88,0.15); color: var(--accent-green); }
.cc-pill-agent { background: rgba(191,90,242,0.15); color: var(--accent-purple); }

/* Шаги внутри карточки - показывают, где именно ты сейчас в пайплайне. */
.cc-steps { display: flex; gap: 6px; flex-wrap: wrap; padding: 0 16px 12px; border-bottom: 1px solid rgba(255,255,255,0.06); }
.cc-step { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 600; color: var(--text-secondary); opacity: 0.55; }
.cc-step:not(:last-child):after { content: '·'; margin-left: 6px; opacity: 0.5; }
.cc-step b { display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px; border-radius: 50%; background: rgba(255,255,255,0.08); font-size: 9px; }
.cc-step.done { opacity: 0.8; color: var(--accent-green); }
.cc-step.done b { background: rgba(48,209,88,0.18); color: var(--accent-green); }
.cc-step.active { opacity: 1; color: var(--accent-blue); }
.cc-step.active b { background: var(--accent-blue); color: #fff; }

.cc-body { padding: 16px; }

/* ФОРМА */
.cc-label { display: block; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-secondary); margin: 18px 0 0 2px; }
.cc-body > .cc-label:first-child, .cc-body > .cc-topic-row:first-child { margin-top: 0; }
.cc-label-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 18px 0 0; }
.cc-label-row .cc-label { margin: 0; }
.cc-optional { text-transform: none; letter-spacing: 0; font-weight: 500; opacity: 0.65; }
