}

function crmMatches(record, fields) {
    const q = crmSearch.trim().toLowerCase();
    if (!q) return true;
    return fields.some(f => String(record[f] || '').toLowerCase().includes(q));
}

// ---------- ОБЗОР ----------
function renderCrmOverview() {
