cat >> styles.css <<'CSS_EOF'

/* ============================================================
   CRM
   Объекты по образцу Twenty (компании / контакты / сделки / задачи)
   плюс контентная доска, переехавшая сюда из вкладки «Канбан».
   ============================================================ */

.crm-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.crm-header-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }

/* Переключатель объектов - подчёркиванием, а не рамками: он живёт прямо под
   заголовком страницы, и вторая рамочная группа рядом с шапкой шумит. */
.crm-objects {
    display: flex; gap: 4px; padding: 0 24px; overflow-x: auto;
    border-bottom: 1px solid var(--separator);
}
.crm-obj {
    flex-shrink: 0; padding: 12px 14px; border: none; background: none; cursor: pointer;
    color: var(--text-secondary); font-size: 13px; font-weight: 600; font-family: inherit;
    border-bottom: 2px solid transparent; margin-bottom: -1px; white-space: nowrap;
    transition: color 0.15s ease, border-color 0.15s ease;
}
.crm-obj:hover { color: var(--text-primary); }
.crm-obj.on { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }
.crm-obj-count {
    display: inline-block; margin-left: 5px; padding: 1px 6px; border-radius: 6px;
    background: rgba(255,255,255,0.08); color: var(--text-secondary); font-size: 11px;
}
.crm-obj.on .crm-obj-count { background: rgba(10,132,255,0.18); color: var(--accent-blue); }

.crm-body { padding: 20px 24px 40px; max-width: 1600px; }
.crm-body .kanban-board { padding: 0; height: auto; min-height: 60vh; }

.merged-stat b.bad { color: var(--accent-red); }

.crm-overview-grid { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 16px; align-items: start; }
.crm-panel { background: var(--bg-grouped); border: 1px solid rgba(255,255,255,0.06); border-radius: 14px; padding: 16px; }
.crm-panel-head {
    display: flex; align-items: center; justify-content: space-between; gap: 10px;
    font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px;
    color: var(--text-secondary); margin-bottom: 12px;
}
.crm-panel .form-select, .crm-panel .form-textarea, .crm-panel .form-input { margin-bottom: 10px; }

/* Воронка: длина полосы = доля стадии от самой населённой, поэтому затык
   виден глазом, а не вычитается из чисел. */
.crm-funnel-row {
    display: grid; grid-template-columns: 130px 1fr 36px 110px; gap: 10px; align-items: center;
    padding: 7px 0; cursor: pointer; font-size: 12.5px;
}
.crm-funnel-row:hover .crm-funnel-name { color: var(--text-primary); }
.crm-funnel-name { color: var(--text-secondary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.crm-funnel-bar { height: 8px; border-radius: 4px; background: rgba(255,255,255,0.06); overflow: hidden; }
.crm-funnel-bar i { display: block; height: 100%; border-radius: 4px; }
.crm-funnel-num { text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }
.crm-funnel-sum { text-align: right; color: var(--text-secondary); font-variant-numeric: tabular-nums; }

/* ТАБЛИЦЫ */
.crm-toolbar { display: flex; gap: 10px; align-items: center; margin-bottom: 14px; }
.crm-search { max-width: 420px; margin: 0; }
.crm-table-wrap { overflow-x: auto; border: 1px solid rgba(255,255,255,0.06); border-radius: 12px; }
.crm-table { width: 100%; border-collapse: collapse; font-size: 12.5px; background: var(--bg-grouped); }
.crm-table th {
    padding: 10px 12px; text-align: left; font-size: 11px; text-transform: uppercase;
    letter-spacing: 0.4px; color: var(--text-secondary); font-weight: 700;
    background: var(--bg-grouped-active); position: sticky; top: 0; white-space: nowrap;
}
.crm-table td { padding: 4px 6px; border-bottom: 1px solid rgba(255,255,255,0.05); vertical-align: middle; }
.crm-table tbody tr:hover { background: rgba(255,255,255,0.03); }

/* Ячейка-инпут без рамки, пока её не тронули: таблица должна читаться как
   таблица, а не как сетка полей ввода. */
.crm-cell {
    width: 100%; padding: 7px 8px; border: 1px solid transparent; border-radius: 7px;
    background: transparent; color: var(--text-primary); font-family: inherit; font-size: 12.5px;
}
.crm-cell:hover { background: rgba(255,255,255,0.05); }
.crm-cell:focus { outline: none; border-color: var(--accent-blue); background: var(--bg-base); }
select.crm-cell { -webkit-appearance: none; appearance: none; cursor: pointer; }
.crm-link {
    border: none; background: none; padding: 7px 8px; text-align: left; cursor: pointer;
    color: var(--text-primary); font-weight: 600; font-family: inherit; font-size: 12.5px;
}
.crm-link:hover { color: var(--accent-blue); text-decoration: underline; }

/* ДОСКА СДЕЛОК */
.crm-board { align-items: flex-start; }
.crm-stage-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 7px; vertical-align: middle; }
.crm-column-sum { padding: 0 4px 8px; font-size: 11px; color: var(--text-secondary); font-variant-numeric: tabular-nums; }
.crm-deal-card { cursor: pointer; }
.crm-deal-title { font-weight: 600; font-size: 13.5px; margin-bottom: 4px; }
.crm-deal-company { font-size: 12px; color: var(--text-secondary); margin-bottom: 6px; }
.crm-deal-amount { font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; }

/* ЗАДАЧИ */
.crm-task { display: flex; align-items: flex-start; gap: 10px; padding: 9px 0; border-bottom: 1px solid rgba(255,255,255,0.05); }
.crm-task:last-child { border-bottom: none; }
.crm-task input[type="checkbox"] { margin-top: 2px; width: 16px; height: 16px; accent-color: var(--accent-blue); flex-shrink: 0; }
.crm-task-body { flex: 1; min-width: 0; }
.crm-task-text { font-size: 13px; line-height: 1.4; overflow-wrap: anywhere; }
.crm-task.done .crm-task-text { text-decoration: line-through; color: var(--text-secondary); }
.crm-task-linked { font-size: 11.5px; color: var(--text-secondary); margin-top: 3px; }
.crm-task-due { font-size: 11.5px; color: var(--text-secondary); white-space: nowrap; font-variant-numeric: tabular-nums; }
.crm-task-due.overdue { color: var(--accent-red); font-weight: 600; }
.crm-task-del { border: none; background: none; color: var(--text-secondary); cursor: pointer; padding: 0 2px; font-size: 12px; }
.crm-task-del:hover { color: var(--accent-red); }

/* СТРАНИЦА ЗАПИСИ */
.crm-record-layout {
    display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 24px;
    padding: 24px; max-width: 1500px; align-items: start;
}
.crm-record-main { min-width: 0; }
.crm-record-side { position: sticky; top: 24px; display: flex; flex-direction: column; gap: 14px; }
.crm-fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; }
.crm-field .cc-label { margin-top: 0; }

.crm-script { margin-top: 22px; border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; overflow: hidden; }
.crm-script > summary { cursor: pointer; padding: 12px 14px; background: rgba(255,255,255,0.04); font-size: 13px; font-weight: 600; list-style: none; }
.crm-script > summary::-webkit-details-marker { display: none; }
.crm-script-body { padding: 12px 14px; font-size: 13px; line-height: 1.6; white-space: pre-wrap; color: var(--text-secondary); }
.crm-script .cc-secondary { margin: 0 14px 14px; }

.crm-related { margin-top: 24px; }
.crm-related-row {
    display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1fr); gap: 10px;
    align-items: center; padding: 10px 12px; margin-bottom: 6px; cursor: pointer;
    background: var(--bg-grouped); border: 1px solid rgba(255,255,255,0.05); border-radius: 10px;
    font-size: 12.5px; color: var(--text-secondary);
}
.crm-related-row:hover { border-color: rgba(255,255,255,0.18); }
.crm-related-row b { color: var(--text-primary); font-weight: 600; overflow: hidden; text-overflow: ellipsis; }

.crm-timeline { display: flex; flex-direction: column; gap: 8px; }
.crm-tl-item { background: var(--bg-grouped); border: 1px solid rgba(255,255,255,0.05); border-radius: 11px; padding: 11px 13px; }
.crm-tl-head { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.crm-tl-kind { font-size: 11px; font-weight: 700; color: var(--text-secondary); }
.crm-tl-date { font-size: 11px; color: var(--text-secondary); margin-left: auto; font-variant-numeric: tabular-nums; }
.crm-tl-body { font-size: 13px; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; }
.crm-tl-due { font-size: 11.5px; color: var(--accent-orange); margin-top: 5px; }

@media (max-width: 1023px) {
    .crm-overview-grid, .crm-record-layout { grid-template-columns: minmax(0, 1fr); }
    .crm-record-side { position: static; }
}
@media (max-width: 767px) {
    .crm-header { align-items: stretch; }
    .crm-header-actions { width: 100%; }
    .crm-objects, .crm-body { padding-left: 16px; padding-right: 16px; }
    .crm-record-layout { padding: 16px; }
    .crm-funnel-row { grid-template-columns: 92px 1fr 30px; }
    .crm-funnel-sum { display: none; }
    .crm-related-row { grid-template-columns: minmax(0, 1fr); gap: 4px; }
}
CSS_EOF
pkill -f "concurrently" 2>/dev/null; sleep 1; pkill -f "server/index.js" 2>/dev/null; sleep 1; echo done
